--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- Tests/Verify-PackagedFix.ps1 ---
$ErrorActionPreference = 'Stop'
$root = Split-Path $PSScriptRoot -Parent
$header = Get-Content (Join-Path $root 'Source/PixelArena/ArenaGameMode.h') -Raw
$source = Get-Content (Join-Path $root 'Source/PixelArena/ArenaGameMode.cpp') -Raw
$config = Get-Content (Join-Path $root 'Config/DefaultGame.ini') -Raw
$failures = 0
if ($header -match 'UPROPERTY\([^)]*\)\s*TObjectPtr<UArenaScoreTracker>\s+ScoreTracker\b') {
    Write-Output 'PASS: ScoreTracker has a reflected strong UObject reference.'
} else {
    Write-Output 'FAIL: ScoreTracker lacks a reflected strong UObject reference.'
    $failures++
}
$paletteMatch = [regex]::Match($source, 'LoadObject<UArenaPalette>\(nullptr, TEXT\("([^"]+)"\)\)')
if (-not $paletteMatch.Success) { throw 'Expected a literal UArenaPalette LoadObject path; received no matching load.' }
$paletteDirectory = $paletteMatch.Groups[1].Value -replace '/[^/]+$', ''
$packaging = [regex]::Match($config, '(?ms)^\[/Script/UnrealEd.ProjectPackagingSettings\]\s*\r?\n(.*?)(?=^\[|\z)').Groups[1].Value
$cookEntry = '+DirectoriesToAlwaysCook=(Path="' + $paletteDirectory + '")'
if (($packaging -split '\r?\n') -contains $cookEntry) {
    Write-Output 'PASS: Runtime palette directory is explicitly included in cooking.'
} else {
    Write-Output 'FAIL: Runtime palette directory is missing from explicit cooking.'
    $failures++
}
if ($failures -gt 0) { exit 1 }


--- result.json ---
{
  "crash_cause": "ScoreTracker is created with NewObject but stored in an unreflected raw UArenaScoreTracker pointer. The GameMode therefore does not hold a GC-visible strong reference; passing this as Outer does not keep the tracker alive. Garbage collection can reclaim it, leaving a dangling pointer used by OnGoalScored. The packaged log records garbage collection at 21:05:13 followed by an access violation in UArenaScoreTracker::AddPoints from OnGoalScored at 21:05:27. Fixed by declaring ScoreTracker as UPROPERTY() TObjectPtr<UArenaScoreTracker>. Hud and Palette already have reflected references; FArenaStats is plain C++ data with explicit new/delete ownership and must not be made a UObject property.",
  "no_colors_cause": "DA_Primary is loaded only by a literal runtime LoadObject path. With bCookAll=False and only the Arena map and Effects directory explicitly cooked, this reference does not ensure inclusion of the palette asset. The packaged log reports the missing /Game/Data/Palettes/DA_Primary package, failed ArenaPalette lookup, and fallback gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook while preserving the existing cooking settings. Assumption: the correctly named palette asset exists in the full project, consistent with the working editor; assets are absent from this supplied snapshot.",
  "validation": "Tests/Verify-PackagedFix.ps1 failed both static regression checks before the fix and passed both after it; result.json also parsed successfully. Runtime validation and compilation are unavailable because this machine has no Unreal Engine and the supplied snapshot omits referenced implementation headers and assets. A full-project clean packaged build should verify palette inclusion and scoring after forced garbage collection."
}
